import json
import numpy as np
import jax
import jax.numpy as jnp


def compute_basic_reduce(inp_path):
    x = jnp.array(np.load(inp_path))
    return jnp.mean(x, axis=1)


def compute_map_square(inp_path):
    x = jnp.array(np.load(inp_path))
    square_rows = jax.vmap(jnp.square)
    return square_rows(x)


def compute_grad_logistic(inp_path):
    data = np.load(inp_path)
    x = jnp.array(data["x"])
    y = jnp.array(data["y"])
    w = jnp.array(data["w"])

    def loss_fn(w_):
        logits = jnp.dot(x, w_)
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    return jax.grad(loss_fn)(w)


def compute_scan_rnn(inp_path):
    data = np.load(inp_path)
    seq = jnp.array(data["seq"])
    init = jnp.array(data["init"])
    Wx = jnp.array(data["Wx"])
    Wh = jnp.array(data["Wh"])
    b = jnp.array(data["b"])

    def step(h, x_t):
        h_new = jnp.tanh(Wx @ x_t + Wh @ h + b)
        return h_new, h_new

    _, states = jax.lax.scan(step, init, seq)
    return states


def compute_jit_mlp(inp_path):
    data = np.load(inp_path)
    X = jnp.array(data["X"])
    W1 = jnp.array(data["W1"])
    b1 = jnp.array(data["b1"])
    W2 = jnp.array(data["W2"])
    b2 = jnp.array(data["b2"])

    def mlp_fn(X_, W1_, b1_, W2_, b2_):
        hidden = jnp.maximum(0.0, X_ @ W1_ + b1_)
        return hidden @ W2_ + b2_

    mlp_jit = jax.jit(mlp_fn)
    return mlp_jit(X, W1, b1, W2, b2)


def main():
    with open("problem.json", "r", encoding="utf-8") as f:
        tasks = json.load(f)

    for task in tasks:
        desc = task["description"]
        inp = task["input"]
        out = task["output"]
        task_id = task["id"]

        if task_id == "basic_reduce":
            result = compute_basic_reduce(inp)
        elif task_id == "map_square":
            result = compute_map_square(inp)
        elif task_id == "grad_logistic":
            result = compute_grad_logistic(inp)
        elif task_id == "scan_rnn":
            result = compute_scan_rnn(inp)
        elif task_id == "jit_mlp":
            result = compute_jit_mlp(inp)
        else:
            raise ValueError(f"Unknown task id: {task_id} ({desc})")

        np.save(out, np.array(result))


if __name__ == "__main__":
    main()
